\copy (select parcel_code pnu, count(*) n_rows, sum((attributes->>'gross_floor_area_m2')::float) gfa_m2, sum((attributes->>'gross_floor_area_m2')::float) filter (where attributes->>'building_use' like '%공동주택%' or attributes->>'building_use' like '%아파트%') gfa_apt_m2, sum(nullif(attributes->>'households','')::float) households, min(approval_year) min_year, max(approval_year) max_year from building_register group by 1) to stdout with csv header
